{
  "conversations": [
    {
      "title": "Accept or decline a dance",
      "lines": [
        { "speaker": "partner", "text": "Would you like to dance?" },
        { "speaker": "you", "text": "I'd love to." },
        { "speaker": "you", "text": "I'm just watching right now, thanks.", "or": true },
        { "speaker": "partner", "text": "Awesome, let's go." },
        { "speaker": "partner", "text": "No worries, enjoy the music.", "or": true }
      ]
    },
    {
      "title": "Compliment someone's dancing",
      "lines": [
        { "speaker": "you", "text": "You're a great dancer." },
        { "speaker": "partner", "text": "Thank you so much." },
        { "speaker": "you", "text": "Where'd you learn to dance?" },
        { "speaker": "partner", "text": "I take classes here in town." },
        { "speaker": "you", "text": "That's really cool." }
      ]
    },
    {
      "title": "Chat between songs",
      "lines": [
        { "speaker": "partner", "text": "Do you come here often?" },
        { "speaker": "you", "text": "This is my first time here." },
        { "speaker": "you", "text": "I come here almost every week.", "or": true },
        { "speaker": "partner", "text": "Welcome to the club." },
        { "speaker": "partner", "text": "Nice, it's a great spot.", "or": true },
        { "speaker": "you", "text": "I love the live band." }
      ]
    }
  ]
}
